                        num = 10 as c_int * num
                            + (*ptr as c_int - '0' as i32);
                        if num > OPNG_BITSET_ELT_MAX as c_int {
                            num = OPNG_BITSET_ELT_MAX as c_int;
                            err_range = 1 as c_int;
                        }
                        ptr = ptr.offset(1);
