                result |= if num1 <= num2 {
                    ((1 as c_uint) << num2 - num1 << 1 as c_int)
                        .wrapping_sub(1 as c_uint)
                        << num1
                } else {
                    0 as c_uint
                };
                result &= mask_set as c_uint;
            } else {
                err_range = 1 as c_int;
            }
            state = 0 as c_int;
        }
        if *ptr as c_int == ',' as i32 || *ptr as c_int == ';' as i32 {
            ptr = ptr.offset(1);
        } else {
            if !(*ptr as c_int == '-' as i32) {
                break;
            }
            err_invalid = 1 as c_int;
            break;
